b:includable.script:
    (function() {
      var items = ;
      var msgs = ;
      var config = ;

// 
      var cursor = null;
      if (items && items.length > 0) {
        cursor = parseInt(items[items.length - 1].timestamp) + 1;
      }

      var bodyFromEntry = function(entry) {
        var text = (entry &&
                    ((entry.content && entry.content.$t) ||
                     (entry.summary && entry.summary.$t))) ||
            '';
        if (entry && entry.gd$extendedProperty) {
          for (var k in entry.gd$extendedProperty) {
            if (entry.gd$extendedProperty[k].name == 'blogger.contentRemoved') {
              return '<span class="deleted-comment">' + text + '</span>';
            }
          }
        }
        return text;
      }

      var parse = function(data) {
        cursor = null;
        var comments = [];
        if (data && data.feed && data.feed.entry) {
          for (var i = 0, entry; entry = data.feed.entry[i]; i++) {
            var comment = {};
            // comment ID, parsed out of the original id format
            var id = /blog-(\d+).post-(\d+)/.exec(entry.id.$t);
            comment.id = id ? id[2] : null;
            comment.body = bodyFromEntry(entry);
            comment.timestamp = Date.parse(entry.published.$t) + '';
            if (entry.author && entry.author.constructor === Array) {
              var auth = entry.author[0];
              if (auth) {
                comment.author = {
                  name: (auth.name ? auth.name.$t : undefined),
                  profileUrl: (auth.uri ? auth.uri.$t : undefined),
                  avatarUrl: (auth.gd$image ? auth.gd$image.src : undefined)
                };
              }
            }
            if (entry.link) {
              if (entry.link[2]) {
                comment.link = comment.permalink = entry.link[2].href;
              }
              if (entry.link[3]) {
                var pid = /.*comments\/default\/(\d+)\?.*/.exec(entry.link[3].href);
                if (pid && pid[1]) {
                  comment.parentId = pid[1];
                }
              }
            }
            comment.deleteclass = 'item-control blog-admin';
            if (entry.gd$extendedProperty) {
              for (var k in entry.gd$extendedProperty) {
                if (entry.gd$extendedProperty[k].name == 'blogger.itemClass') {
                  comment.deleteclass += ' ' + entry.gd$extendedProperty[k].value;
                } else if (entry.gd$extendedProperty[k].name == 'blogger.displayTime') {
                  comment.displayTime = entry.gd$extendedProperty[k].value;
                }
              }
            }
            comments.push(comment);
          }
        }
        return comments;
      };

      var paginator = function(callback) {
        if (hasMore()) {
          var url = config.feed + '?alt=json&v=2&orderby=published&reverse=false&max-results=50';
          if (cursor) {
            url += '&published-min=' + new Date(cursor).toISOString();
          }
          window.bloggercomments = function(data) {
            var parsed = parse(data);
            cursor = parsed.length < 50 ? null
                : parseInt(parsed[parsed.length - 1].timestamp) + 1
            callback(parsed);
            window.bloggercomments = null;
          }
          url += '&callback=bloggercomments';
          var script = document.createElement('script');
          script.type = 'text/javascript';
          script.src = url;
          document.getElementsByTagName('head')[0].appendChild(script);
        }
      };
      var hasMore = function() {
        return !!cursor;
      };
      var getMeta = function(key, comment) {
        if ('iswriter' == key) {
          var matches = !!comment.author
              && comment.author.name == config.authorName
              && comment.author.profileUrl == config.authorUrl;
          return matches ? 'true' : '';
        } else if ('deletelink' == key) {
          return config.baseUri + '/comment/delete/'
               + config.blogId + '/' + comment.id;
        } else if ('deleteclass' == key) {
          return comment.deleteclass;
        }
        return '';
      };

      var replybox = null;
      var replyUrlParts = null;
      var replyParent = undefined;

      var onReply = function(commentId, domId) {
        if (replybox == null) {
          // lazily cache replybox, and adjust to suit this style:
          replybox = document.getElementById('comment-editor');
          if (replybox != null) {
            replybox.height = '250px';
            replybox.style.display = 'block';
            replyUrlParts = replybox.src.split('#');
          }
        }
        if (replybox && (commentId !== replyParent)) {
          replybox.src = '';
          document.getElementById(domId).insertBefore(replybox, null);
          replybox.src = replyUrlParts[0]
              + (commentId ? '&parentID=' + commentId : '')
              + '#' + replyUrlParts[1];
          replyParent = commentId;
        }
      };

      var hash = (window.location.hash || '#').substring(1);
      var startThread, targetComment;
      if (/^comment-form_/.test(hash)) {
        startThread = hash.substring('comment-form_'.length);
      } else if (/^c[0-9]+$/.test(hash)) {
        targetComment = hash.substring(1);
      }

      // Configure commenting API:
      var configJso = {
        'maxDepth': config.maxThreadDepth
      };
      var provider = {
        'id': config.postId,
        'data': items,
        'loadNext': paginator,
        'hasMore': hasMore,
        'getMeta': getMeta,
        'onReply': onReply,
        'rendered': true,
        'initComment': targetComment,
        'initReplyThread': startThread,
        'config': configJso,
        'messages': msgs
      };

      var render = function() {
        if (window.goog && window.goog.comments) {
          var holder = document.getElementById('comment-holder');
          window.goog.comments.render(holder, provider);
        }
      };

      // render now, or queue to render when library loads:
      if (window.goog && window.goog.comments) {
        render();
      } else {
        window.goog = window.goog || {};
        window.goog.comments = window.goog.comments || {};
        window.goog.comments.loadQueue = window.goog.comments.loadQueue || [];
        window.goog.comments.loadQueue.push(render);
      }
    })();
//

body.script:
//

// Bottom nav helper — kept global (not inside LiveTV) so it works from any
// page, including post pages where LiveTV's tab system doesn't exist.
var S803Nav = {
  _drawerMode: null,
  _drawerOrigin: null, // kept for backwards compat but no longer needed (clone-based drawer)

  setActive: function(btn) {
    document.querySelectorAll('.s803-bottom-nav button').forEach(function(b) { b.classList.remove('is-active'); });
    if (btn) btn.classList.add('is-active');
  },

  goHome: function(url) {
    var drawer = document.getElementById('s803Drawer');
    var isOpen = drawer && drawer.classList.contains('is-open');
    if (isOpen) this.closeDrawer();
    if (document.body.classList.contains('index-view')) {
      this.setActive(document.querySelector('.s803-bottom-nav button[data-nav="home"]'));
      if (isOpen) return; // already home, drawer just needed closing
      window.scrollTo({ top: 0, behavior: 'smooth' });
      return;
    }
    location.href = url;
  },

  // MANUS: Task 5 – Bottom-nav drawer now uses a cloned copy instead of moving DOM nodes,
  // so the original tab panels stay in place and layout shifts on close are avoided.
  goTab: function(tabId, btn, label) {
    var isHomepage = document.body.classList.contains('index-view');
    if (!isHomepage) {
      location.href = '/';
      return;
    }
    // MANUS: find the active tab button by role attribute instead of onclick pattern
    var navBtn = document.querySelector('.tabs-nav button[aria-controls="' + tabId + '"]');
    if (navBtn && typeof LiveTV !== 'undefined') {
      LiveTV.showTab(navBtn, tabId);
    }
    var panel = document.getElementById(tabId);
    var body = document.getElementById('s803DrawerBody');
    var drawer = document.getElementById('s803Drawer');
    var backdrop = document.getElementById('s803DrawerBackdrop');
    if (!panel || !body || !drawer) return;

    this.setActive(btn);
    this._drawerMode = 'panel';
    // MANUS: Clone the panel content instead of moving the DOM node
    body.innerHTML = '';
    var clone = panel.cloneNode(true);
    clone.classList.add('is-active');
    clone.style.maxHeight = 'none';
    clone.style.overflow = 'visible';
    body.appendChild(clone);
    document.getElementById('s803DrawerTitle').textContent = label || '';
    drawer.classList.add('is-open');
    backdrop.classList.add('is-open');
    document.body.classList.add('s803-drawer-lock');

    // Re-wire dynamic cards inside the clone so share buttons and click handlers work
    if (typeof LiveTV !== 'undefined') {
      clone.querySelectorAll('.event-card').forEach(card => LiveTV.wireDynamicCard(card));
    }
  },

  // Replays: posts labeled "replay", fetched from the blog's own JSON feed.
  openReplays: function(btn) {
    var body = document.getElementById('s803DrawerBody');
    var drawer = document.getElementById('s803Drawer');
    var backdrop = document.getElementById('s803DrawerBackdrop');
    if (!body || !drawer) return;

    this.setActive(btn);
    this._drawerMode = 'content';
    this._drawerOrigin = null;
    document.getElementById('s803DrawerTitle').textContent = 'Replays';
    body.innerHTML = '<div class="s803-drawer-loading">Loading replays\u2026</div>';
    drawer.classList.add('is-open');
    backdrop.classList.add('is-open');
    document.body.classList.add('s803-drawer-lock');

    fetch('/feeds/posts/summary/-/replay?alt=json&max-results=20')
      .then(function(r) { return r.json(); })
      .then(function(data) {
        var entries = (data.feed && data.feed.entry) || [];
        if (!entries.length) {
          body.innerHTML = '<div class="s803-drawer-empty">No replays posted yet.</div>';
          return;
        }
        var html = '<div class="s803-replay-list">';
        entries.forEach(function(entry) {
          var title = entry.title.$t;
          var link = '#';
          (entry.link || []).forEach(function(l) { if (l.rel === 'alternate') link = l.href; });
          var defaultThumb = "https://via.placeholder.com/160x90?text=No+Thumbnail"; // Default thumbnail
          var thumb = entry.media$thumbnail ? entry.media$thumbnail.url.replace('/s72-c/', '/s160-c/') : defaultThumb;
          html += '<a class="s803-replay-item" href="' + link + '">' +
            (thumb ? '<img alt="" loading="lazy" src="' + thumb + '"/>' : '<div class="s803-replay-noimg">\uD83C\uDFAC</div>') +
            '<span>' + title + '</span></a>';
        });
        html += '</div>';
        body.innerHTML = html;
      })
      .catch(function() {
        body.innerHTML = '<div class="s803-drawer-empty">Couldn\u2019t load replays right now.</div>';
      });
  },

  _historyKey: 's803_history',

  _getHistory: function() {
    try {
      return JSON.parse(localStorage.getItem(this._historyKey) || '[]');
    } catch (e) {
      console.error('Error parsing history from localStorage', e);
      return [];
    }
  },

  _saveHistory: function(history) {
    try {
      localStorage.setItem(this._historyKey, JSON.stringify(history));
    } catch (e) {
      console.error('Error saving history to localStorage', e);
    }
  },

  addHistoryEntry: function(item) {
    let history = this._getHistory();
    // Remove if already exists to bring to front
    history = history.filter(entry => entry.link !== item.link);
    history.unshift(item); // Add to the beginning
    history = history.slice(0, 10); // Keep only the last 10 items
    this._saveHistory(history);
  },

  openHistory: function(btn) {
    var body = document.getElementById('s803DrawerBody');
    var drawer = document.getElementById('s803Drawer');
    var backdrop = document.getElementById('s803DrawerBackdrop');
    if (!body || !drawer) return;

    this.setActive(btn);
    this._drawerMode = 'content';
    this._drawerOrigin = null;
    document.getElementById('s803DrawerTitle').textContent = 'Recently Viewed';

    let history = this._getHistory();
    if (!history.length) {
      body.innerHTML = '<div class="s803-drawer-empty">No recently viewed items.</div>';
      drawer.classList.add('is-open');
      backdrop.classList.add('is-open');
      document.body.classList.add('s803-drawer-lock');
      return;
    }

    let html = '<div class="s803-replay-list">'; // Re-using replay list style for now
    history.forEach(function(item) {
      html += '<a class="s803-replay-item" href="' + item.link + '">\n' +
              (item.thumb ? '<img alt="" loading="lazy" src="' + item.thumb + '"/>' : '<div class="s803-replay-noimg">\uD83C\uDFAC</div>') + '\n' +
              '<span>' + item.title + '</span></a>';
    });
    html += '</div>';
    body.innerHTML = html;
    drawer.classList.add('is-open');
    backdrop.classList.add('is-open');
    document.body.classList.add('s803-drawer-lock');
  },

  closeDrawer: function() {
    var drawer = document.getElementById('s803Drawer');
    var backdrop = document.getElementById('s803DrawerBackdrop');
    if (drawer) drawer.classList.remove('is-open');
    if (backdrop) backdrop.classList.remove('is-open');
    document.body.classList.remove('s803-drawer-lock');

    // MANUS: Task 5 – No longer need to re-insert moved DOM nodes; just clear the clone
    if (this._drawerMode === 'panel' || this._drawerMode === 'content') {
      var body = document.getElementById('s803DrawerBody');
      if (body) body.innerHTML = '';
    }
    this._drawerMode = null;
    this._drawerOrigin = null;
    this.setActive(document.querySelector('.s803-bottom-nav button[data-nav="home"]'));
  },

  focusSearch: function() {
    var drawer = document.getElementById('s803Drawer');
    if (drawer && drawer.classList.contains('is-open')) this.closeDrawer();
    var input = document.getElementById('searchInput');
    if (!input) { location.href = '/'; return; }
    window.scrollTo({ top: 0, behavior: 'smooth' });
    setTimeout(function() { input.focus(); }, 300);
  }
};

var LiveTV = {
  showTab: function(btn, targetId) {
    document.querySelectorAll('.tabs-nav button').forEach(b => b.classList.remove('is-active'));
    btn.classList.add('is-active');
    document.querySelectorAll('.tab-panel').forEach(p => p.classList.remove('is-active'));
    document.getElementById(targetId).classList.add('is-active');
    const catMenu = document.getElementById('category-menu');
    if (catMenu) catMenu.classList.toggle('is-active', targetId === 'events-tab');
  },

  // -- Category filter menu (Football, F1, NASCAR, Boxing, etc.) --
  filterCategory: function(btn) {
    document.querySelectorAll('.category-btn').forEach(b => b.classList.remove('is-active'));
    btn.classList.add('is-active');
    const category = btn.getAttribute('data-category');
    document.querySelectorAll('#events-tab .event-card').forEach(card => {
      const cardCat = card.getAttribute('data-category') || 'other';
      const matches = category === 'all' || cardCat === category;
      card.classList.toggle('is-category-hidden', !matches);
      card.classList.toggle('is-hidden', !matches || card.classList.contains('is-search-hidden'));
    });
    this.insertInfeedAds();
  },

  // -- Firebase Realtime Database: fetch events and build cards dynamically --
  // Uses the public REST API (https://<project>.firebaseio.com/<path>.json) — no SDK/API key needed.
  // Reads the SAME node your Match-day / Highlights-Player tools already write to,
  // so events pushed from any of your tools show up here automatically.
  // MANUS: Task 3 – Firebase Security Rules required:
  // {
  //   "rules": {
  //     "postReactions": {
  //       ".read": true,
  //       ".write": "auth == null"
  //     },
  //     "s803config": {
  //       ".read": true,
  //       ".write": false
  //     },
  //     "livetv": {
  //       ".read": true,
  //       ".write": false
  //     }
  //   }
  // }
  // MANUS: Task 3 – Firebase URL now read from meta tag for configurability
  FIREBASE_URL: (document.querySelector('meta[name="firebase-url"]') || {}).content || 'https://sports-803-1b806-default-rtdb.firebaseio.com',
  // MANUS: Task 4 – Firebase paths defined as top-level constants for maintainability
  FIREBASE_EVENTS_PATH: 's803config/todaysMatches',
  FIREBASE_CHANNELS_PATH: 'livetv/channels',
  fbChannels: {},

  // Maps ESPN/Match-day's leagueId (or broad sport) onto our category menu slugs.
  LEAGUE_TO_CATEGORY: {
    'f1': 'f1', 'motogp': 'motorsport', 'nascar-cup': 'nascar', 'indycar': 'motorsport',
    'nba': 'basketball', 'wnba': 'basketball',
    'nhl': 'hockey', 'mlb': 'baseball', 'nfl': 'nfl',
    'mma-ufc': 'mma', 'boxing': 'boxing'
  },
  resolveCategory: function(ev) {
    if (ev.category) return ev.category; // our own generator sets this explicitly
    if (ev.leagueId && this.LEAGUE_TO_CATEGORY[ev.leagueId]) return this.LEAGUE_TO_CATEGORY[ev.leagueId];
    if (ev.sport === 'football') return 'football';
    if (ev.sport === 'basketball') return 'basketball';
    if (ev.sport === 'motorsport') return 'motorsport';
    return 'other';
  },

  escapeHtml: function(s) {
    return String(s == null ? '' : s).replace(/[&<>"']/g, m => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[m]));
  },

  // ESPN status vocabulary used by the Match-day tool's pushed events.
  FB_LIVE_STATUSES: ['STATUS_IN_PROGRESS', 'STATUS_HALFTIME', 'STATUS_IN_PROGRESS_2', 'STATUS_END_PERIOD', 'STATUS_OVERTIME', 'STATUS_SHOOTOUT'],
  FB_ENDED_STATUSES: ['STATUS_FINAL', 'STATUS_FULL_TIME', 'STATUS_FINAL_OT', 'STATUS_FINAL_PEN', 'STATUS_POSTPONED', 'STATUS_CANCELED', 'STATUS_SUSPENDED', 'STATUS_ABANDONED'],

  buildEventCardEl: function(id, ev) {
    const kickoff = ev.kickoff || ev.time; // ev.time kept for backwards-compat with manually-authored data
    const start = new Date(kickoff).getTime();
    if (!kickoff || isNaN(start)) return null;

    // No explicit duration from ESPN-sourced data — assume a generous
    // default live window, but trust an explicit ended status immediately.
    const duration = parseInt(ev.duration, 10) || 150;
    const end = start + duration * 60000;
    const explicitlyEnded = ev.statusType && this.FB_ENDED_STATUSES.indexOf(ev.statusType) !== -1;
    if (explicitlyEnded || Date.now() > end) return null; // past/finished events never render

    const dt = new Date(kickoff);
    const displayTime = dt.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
    const displayDate = dt.toLocaleDateString([], { day: '2-digit', month: 'short', year: 'numeric' });
    const category = this.resolveCategory(ev);
    const league = ev.leagueName || ev.league || '';

    const card = document.createElement('div');
    card.className = 'event-card';
    card.setAttribute('data-time', kickoff);
    card.setAttribute('data-duration', String(duration));
    card.setAttribute('data-category', category);
    card.setAttribute('data-fb-id', id);

    const homeName = ev.homeName || (ev.home && ev.home.name) || 'Home';
    const homeLogo = ev.homeLogo || (ev.home && ev.home.logo) || '';
    const awayName = ev.awayName || (ev.away && ev.away.name) || '';
    const awayLogo = ev.awayLogo || (ev.away && ev.away.logo) || '';

    const homeBlock = '<div class="event-team">' +
      (homeLogo ? '<img alt="' + this.escapeHtml(homeName) + '" src="' + this.escapeHtml(homeLogo) + '"/>' : '') +
      '<span>' + this.escapeHtml(homeName) + '</span></div>';
    const awayBlock = awayName.trim() ? '<div class="event-team">' +
      (awayLogo ? '<img alt="' + this.escapeHtml(awayName) + '" src="' + this.escapeHtml(awayLogo) + '"/>' : '') +
      '<span>' + this.escapeHtml(awayName) + '</span></div>' : '';

    // Prefer our own generator's multi-stream "channels" array; fall back to
    // a single channel resolved from Match-day's channelKey via livetv/channels.
    let channelsHtml = '';
    if (Array.isArray(ev.channels) && ev.channels.length) {
      channelsHtml = ev.channels.map(ch =>
        '<button class="channel-btn" data-src="' + this.escapeHtml(ch.src) + '">📺 ' + this.escapeHtml(ch.label || 'Stream') + '</button>'
      ).join('');
    } else if (ev.channelKey) {
      const fbCh = this.fbChannels[ev.channelKey];
      const src = fbCh ? (fbCh.src || fbCh.url || fbCh.embed || '') : '';
      const label = ev.channelName || (fbCh && fbCh.name) || 'Watch';
      if (src) channelsHtml = '<button class="channel-btn" data-src="' + this.escapeHtml(src) + '">📺 ' + this.escapeHtml(label) + '</button>';
    }

    card.innerHTML =
      '<div class="overlay"></div>' +
      '<div class="event-status" data-role="status" aria-live="polite">00:00:00</div>' +
      '<div class="event-time">' + displayTime + '</div>' +
      '<div class="event-league"><span>' + this.escapeHtml(league) + '</span><span>' + displayDate + '</span></div>' +
      '<span class="live-score u-hidden" data-role="live-score"></span>' +
      '<div class="event-divider"></div>' +
      homeBlock + awayBlock +
      '<div class="event-channels">' + (channelsHtml || '<!-- no stream assigned yet -->') + '</div>';

    return card;
  },

  // Team names live in separate spans with no "vs" text between them -
  // reconstruct a proper "Team A vs Team B" title for the featured panel.
  cardTitle: function(el) {
    if (el.classList && el.classList.contains('event-card')) {
      const teams = Array.from(el.querySelectorAll('.event-team span')).map(s => s.textContent.trim()).filter(Boolean);
      if (teams.length) return teams.join(' vs ');
    }
    return el.querySelector('span')?.textContent.trim() || el.textContent.trim() || 'Live Stream';
  },

  wireDynamicCard: function(el) {
    // Same wiring init() applies to statically-authored cards, run once per Firebase card.
    if (!el.querySelector('.share-btn')) {
      const title = this.cardTitle(el);
      const btn = document.createElement('div');
      btn.className = 'share-btn';
      btn.innerHTML = '&#128279;';
      btn.title = 'Share this stream';
      btn.onclick = (e) => { e.stopPropagation(); this.share(e, title); };
      el.appendChild(btn);
    }

    const openFrom = (src) => {
      const title = this.cardTitle(el);
      const subtitle = el.querySelector('.event-league span')?.textContent || null;
      const startTime = el.getAttribute('data-time');
      const posterUrl = el.querySelector('img')?.src || null;
      this.openChannel(src, title, subtitle, startTime, posterUrl);
    };

    el.querySelectorAll('[data-src]').forEach(src => {
      src.addEventListener('click', (e) => {
        e.preventDefault();
        e.stopPropagation();
        openFrom(src.getAttribute('data-src'));
      });
    });

    // Clicking the event card itself (not just the small Stream 1/2/3
    // buttons) opens the first available stream - so the whole card is
    // a valid tap target, not just the tiny buttons inside it.
    el.style.cursor = 'pointer';
    el.addEventListener('click', (e) => {
      if (e.target.closest('[data-src]') || e.target.closest('.share-btn')) return;
      const first = el.querySelector('[data-src]');
      if (first) openFrom(first.getAttribute('data-src'));
    });
  },

  renderFirebaseEvents: function(data) {
    const mount = document.getElementById('fb-events-mount');
    const emptyMsg = document.getElementById('fb-events-empty');
    if (!mount) return;
    mount.innerHTML = ''; // clear any previous render before re-drawing
    if (!data) { if (emptyMsg) { emptyMsg.style.display = 'block'; emptyMsg.textContent = "No upcoming events right now — check back soon."; } return; }
    let rendered = 0;
    Object.keys(data).forEach(id => {
      const card = this.buildEventCardEl(id, data[id]);
      if (!card) return; // finished/invalid — never appears
      this.wireDynamicCard(card);
      mount.appendChild(card);
      rendered++;
    });
    if (emptyMsg) emptyMsg.style.display = rendered ? 'none' : 'block';
    this.startEventTimers();
    this.initAccessibility();
  },

  // MANUS: Task 6 – Firebase data caching with localStorage (2-minute TTL)
  _cacheKey: 's803_events_cache',
  _cacheChannelsKey: 's803_channels_cache',
  _cacheTTL: 2 * 60 * 1000, // 2 minutes

  _readCache: function(key) {
    try {
      const raw = localStorage.getItem(key);
      if (!raw) return null;
      const parsed = JSON.parse(raw);
      if (Date.now() - parsed.ts > this._cacheTTL) return null; // expired
      return parsed.data;
    } catch (e) { return null; }
  },

  _writeCache: function(key, data) {
    try {
      localStorage.setItem(key, JSON.stringify({ ts: Date.now(), data: data }));
    } catch (e) { /* storage full or blocked */ }
  },

  loadFirebaseEvents: function() {
    const mount = document.getElementById('fb-events-mount');
    if (!mount) return;

    // MANUS: Task 6 – Check cache first, render immediately if fresh, refresh in background
    const cached = this._readCache(this._cacheKey);
    if (cached) {
      this.renderFirebaseEvents(cached);
    } else {
      // MANUS: Task 11 – No cache yet: show skeleton placeholders while the
      // first fetch is in flight instead of a blank panel. renderFirebaseEvents()
      // clears the mount before drawing real cards, so these are replaced automatically.
      mount.innerHTML = '<div class="skeleton-card"></div><div class="skeleton-card"></div><div class="skeleton-card"></div>';
    }

    // Fetch the channel directory first (best-effort) so channelKey lookups resolve,
    // then fetch and render the events regardless of whether that succeeded.
    const channelsUrl = this.FIREBASE_URL + '/' + this.FIREBASE_CHANNELS_PATH + '.json';
    // MANUS FIX: Removed orderBy/limitToFirst — requires an .indexOn rule that may not exist.
    // Instead, fetch all events and filter/sort client-side (same result, no dependency on DB rules).
    const eventsUrl = this.FIREBASE_URL + '/' + this.FIREBASE_EVENTS_PATH + '.json';

    fetch(channelsUrl)
      .then(r => r.json())
      .then(chData => {
        this.fbChannels = chData || {};
        this._writeCache(this._cacheChannelsKey, chData);
      })
      .catch(() => {
        const cachedCh = this._readCache(this._cacheChannelsKey);
        if (cachedCh) this.fbChannels = cachedCh;
        else this.fbChannels = {};
      })
      .then(() => fetch(eventsUrl))
      .then(r => r.json())
      .then(data => {
        // Guard: if Firebase returns an error object (e.g. missing index), treat as no data
        if (data && typeof data === 'object' && !Array.isArray(data) && data.error) {
          console.warn('Firebase query error:', data.error);
          data = null;
        }
        this._writeCache(this._cacheKey, data);
        if (!cached || JSON.stringify(data) !== JSON.stringify(cached)) {
          this.renderFirebaseEvents(data);
        }
      })
      .catch(() => {
        if (!cached) {
          const emptyMsg = document.getElementById('fb-events-empty');
          if (emptyMsg) { emptyMsg.style.display = 'block'; emptyMsg.textContent = 'Could not reach the events database right now.'; }
        }
      });
  },

  share: function(e, title) {
    e.stopPropagation();
    const url = window.location.origin + window.location.pathname + '?stream=' + encodeURIComponent(title);
    if (navigator.share) {
      navigator.share({ title: title, url: url }).catch(() => {});
    } else {
      navigator.clipboard.writeText(url).then(() => {
        alert('Link copied to clipboard!');
      });
    }
  },

  toggleCinema: function() {
    const btn = document.querySelector('.cinema-toggle');
    const btnText = btn ? btn.querySelector('span') : null;
    const curtain = document.getElementById('cinema-curtain');

    const applyToggle = () => {
      const isCinema = document.body.classList.toggle('is-cinema');
      if (btn) {
        const isPressed = btn.getAttribute('aria-pressed') === 'true';
        btn.setAttribute('aria-pressed', !isPressed);
      }
      if (btnText) btnText.textContent = isCinema ? 'Exit Cinema' : 'Cinema Mode';
      // Drop out of PiP mode while entering/leaving fullscreen cinema
      const panel = document.getElementById('featured-panel');
      if (panel) {
        panel.classList.remove('is-pip');
        panel.style.left = panel.style.top = panel.style.right = panel.style.bottom = '';
      }
    };

    if (!curtain) { applyToggle(); return; }

    curtain.classList.add('is-active');
    setTimeout(() => {
      applyToggle();
      requestAnimationFrame(() => {
        setTimeout(() => curtain.classList.remove('is-active'), 60);
      });
    }, 260);
  },

  // MANUS: dynamically preconnect to the stream host so the browser can resolve
  // DNS / TLS while the user is still reading the title, shaving ~200-600ms off
  // the time-to-first-frame. Safe to call repeatedly - skips existing links.
  preconnectToStreamHost: function(src) {
    try {
      const url = new URL(src, window.location.href);
      const origin = url.protocol + '//' + url.host;
      if (document.querySelector('link[rel="preconnect"][href="' + origin + '"]')) return;
      const link = document.createElement('link');
      link.rel = 'preconnect';
      link.href = origin;
      link.crossOrigin = 'anonymous';
      document.head.appendChild(link);
    } catch (e) {
      // Malformed/relative src - nothing to preconnect to, fail silently.
    }
  },

  openChannel: function(src, title, subtitle, startTime, posterUrl) {
    const panel = document.getElementById('featured-panel');
    if (!panel || !src) return;

    // The featured panel sits behind the Live TV/Events/Replays drawer, so
    // opening a stream while the drawer is open would load it out of view.
    const drawer = document.getElementById('s803Drawer');
    if (drawer && drawer.classList.contains('is-open') && typeof S803Nav !== 'undefined') {
      S803Nav.closeDrawer();
    }

    // MANUS: kick off the DNS/TLS preconnect to the stream host immediately,
    // before any DOM work below, so the connection warms up in parallel.
    this.preconnectToStreamHost(src);

    panel.classList.add('has-iframe');
    panel.style.backgroundImage = 'none';
    panel.dataset.time = startTime || '';

    panel.innerHTML = '';

    // MANUS: build the overlay (title/subtitle/LIVE pill) FIRST and append it
    // before the iframe, so the user gets instant title feedback even though
    // the video itself may take several seconds to start playing.
    const overlay = document.createElement('div');
    overlay.className = 'featured-overlay';
    overlay.innerHTML = `
      <div class="live-pill" data-role="featured-live-pill"><span class="dot"></span> LIVE</div>
      <div class="featured-content">
        <p class="featured-subtitle">${subtitle || 'NOW STREAMING'}</p>
        <h2 class="featured-title">${title || 'Live Broadcast'}</h2>
      </div>
    `;
    panel.appendChild(overlay);

    // MANUS: loading spinner - shown the instant the panel opens, hidden once
    // the iframe fires 'load' (or after an 8s safety timeout so it never spins forever).
    const spinner = document.createElement('div');
    spinner.className = 'featured-spinner';
    spinner.setAttribute('role', 'status');
    spinner.setAttribute('aria-live', 'polite');
    spinner.innerHTML = '<span class="spinner-ring"></span><span class="sr-only" style="position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0);">Loading stream…</span>';
    panel.appendChild(spinner);

    const iframe = document.createElement('iframe');
    iframe.src = src;
    iframe.width = '100%';
    iframe.height = '100%';
    iframe.frameBorder = '0';
    iframe.allow = 'autoplay; encrypted-media; fullscreen';
    iframe.allowFullscreen = true;

    // MANUS: hide the spinner + fade in the iframe once it actually loads,
    // with an 8s cap so a slow/broken stream doesn't spin forever.
    let spinnerDismissed = false;
    const dismissSpinner = () => {
      if (spinnerDismissed) return;
      spinnerDismissed = true;
      iframe.classList.add('is-loaded');
      spinner.classList.add('is-hidden');
      setTimeout(() => spinner.remove(), 400);
    };
    iframe.addEventListener('load', dismissSpinner);
    setTimeout(dismissSpinner, 8000);

    panel.appendChild(iframe);

    const closeBtn = document.createElement('button');
    closeBtn.className = 'pip-close';
    closeBtn.setAttribute('aria-label', 'Close mini player');
    closeBtn.innerHTML = '&#10005;';
    closeBtn.addEventListener('click', (e) => {
      e.stopPropagation();
      panel.classList.remove('is-pip');
      panel.style.left = panel.style.top = panel.style.right = panel.style.bottom = '';
    });
    panel.appendChild(closeBtn);

    // Mute hint - purely an informational nudge, can't control cross-origin iframe audio directly
    const muteHint = document.createElement('div');
    muteHint.className = 'mute-hint';
    // MANUS: Task 5 – Improved mute hint text and extended visibility to 8 seconds
    muteHint.textContent = 'Audio may be muted – use player controls';
    panel.appendChild(muteHint);
    const dismissHint = () => muteHint.classList.add('is-hidden');
    panel.addEventListener('click', dismissHint, { once: true });
    setTimeout(dismissHint, 8000);

    if (startTime) {
      this.updateFeaturedStatus();
    } else {
      panel.classList.add('is-live-pulse');
    }

    this.sampleAmbientColor(posterUrl, panel);
    this.loadReactions(title || src);

    // MANUS: skip/soften scrolling if the panel is already visible - an instant
    // scroll (or no scroll at all) reads as faster than an animated smooth scroll here.
    const rect = panel.getBoundingClientRect();
    const alreadyVisible = rect.top >= 0 && rect.bottom <= (window.innerHeight || document.documentElement.clientHeight);
    if (!alreadyVisible) {
      panel.scrollIntoView({ behavior: 'instant', block: 'center' });
    }

    // Add to history
    S803Nav.addHistoryEntry({
      title: title || 'Live Broadcast',
      link: src,
      thumb: posterUrl || ''
    });
  },

  updateFeaturedStatus: function() {
    const panel = document.getElementById('featured-panel');
    if (!panel) return;
    const time = panel.dataset.time;
    const pill = panel.querySelector('[data-role="featured-live-pill"]');
    if (!time || !pill) return;

    const start = new Date(time).getTime();
    if (isNaN(start)) return;
    const now = Date.now();

    if (now >= start) {
      pill.classList.remove('is-countdown');
      pill.innerHTML = '<span class="dot"></span> LIVE';
      panel.classList.add('is-live-pulse');
    } else {
      const d = start - now;
      const h = Math.floor(d / 3600000);
      const m = Math.floor((d % 3600000) / 60000);
      const s = Math.floor((d % 60000) / 1000);
      pill.classList.add('is-countdown');
      pill.textContent = `KICKS OFF IN ${h}h ${m}m ${s}s`;
      panel.classList.remove('is-live-pulse');
    }
  },

  sampleAmbientColor: function(imgUrl, panel) {
    if (!imgUrl || !panel) return;
    try {
      const img = new Image();
      img.crossOrigin = 'anonymous';
      img.onload = () => {
        try {
          const canvas = document.createElement('canvas');
          canvas.width = 16;
          canvas.height = 16;
          const ctx = canvas.getContext('2d');
          ctx.drawImage(img, 0, 0, 16, 16);
          const data = ctx.getImageData(0, 0, 16, 16).data;
          let r = 0, g = 0, b = 0, count = 0;
          for (let i = 0; i < data.length; i += 4) {
            r += data[i]; g += data[i + 1]; b += data[i + 2]; count++;
          }
          r = Math.round(r / count); g = Math.round(g / count); b = Math.round(b / count);
          panel.style.setProperty('--ambient-glow', `rgba(${r}, ${g}, ${b}, 0.55)`);
        } catch (e) {
          // Image likely blocked canvas read due to missing CORS headers - fail silently
        }
      };
      img.src = imgUrl;
    } catch (e) {}
  },

  startClock: function() {
    const el = document.getElementById('site-clock');
    if (!el) return;
    setInterval(() => {
      const now = new Date();
      el.textContent = now.toTimeString().split(' ')[0];
    }, 1000);
  },

  sortEvents: function() {
    const container = document.getElementById('events-tab');
    if (!container) return;
    const cards = Array.from(container.querySelectorAll('.event-card'));

    cards.sort((a, b) => {
      const now = Date.now();
      const aStart = new Date(a.getAttribute('data-time')).getTime();
      const aEnd = aStart + (parseInt(a.getAttribute('data-duration'), 10) || 120) * 60000;
      const bStart = new Date(b.getAttribute('data-time')).getTime();
      const bEnd = bStart + (parseInt(b.getAttribute('data-duration'), 10) || 120) * 60000;

      const getStatus = (start, end) => {
        if (now > end) return 2;
        if (now >= start) return 0;
        return 1;
      };

      const aStatus = getStatus(aStart, aEnd);
      const bStatus = getStatus(bStart, bEnd);

      if (aStatus !== bStatus) return aStatus - bStatus;
      return aStart - bStart;
    });

    cards.forEach(card => container.appendChild(card));
    this.insertInfeedAds();
  },

  insertInfeedAds: function() {
    const container = document.getElementById('events-tab');
    if (!container) return;

    container.querySelectorAll('.ad-infeed').forEach(el => el.remove());

    const cards = Array.from(container.querySelectorAll('.event-card:not(.is-hidden)'));
    for (let i = 2; i < cards.length; i += 3) {
      const ad = document.createElement('div');
      ad.className = 'ad-slot ad-infeed';
      ad.innerHTML = '<span>Ad Placement C</span>';
      cards[i].after(ad);
    }
  },

  // MANUS: Task 1 – Optimised countdown: IntersectionObserver gates visibility,
  // requestAnimationFrame drives the tick so we skip frames when off-screen.
  _visibleCards: new Set(),
  _timerRunning: false,
  _lastTimerTick: 0,

  startEventTimers: function() {
    const cards = document.querySelectorAll('.event-card');
    if (cards.length === 0) return;

    // MANUS: Track which cards are currently visible in the viewport
    if ('IntersectionObserver' in window) {
      this._io = new IntersectionObserver((entries) => {
        entries.forEach(entry => {
          if (entry.isIntersecting) {
            this._visibleCards.add(entry.target);
          } else {
            this._visibleCards.delete(entry.target);
          }
        });
      }, { rootMargin: '100px' });
      cards.forEach(c => this._io.observe(c));
    } else {
      // Fallback: consider all cards visible
      cards.forEach(c => this._visibleCards.add(c));
    }

    const updateAll = () => {
      let needsSort = false;
      // MANUS: Only update cards that are visible (or all if IO not available)
      const targetCards = this._visibleCards.size > 0 ? this._visibleCards : cards;
      targetCards.forEach(card => {
        const time = card.getAttribute('data-time');
        const duration = parseInt(card.getAttribute('data-duration'), 10) || 120;
        const status = card.querySelector('[data-role="status"]');
        if (!time || !status) return;

        const start = new Date(time).getTime();
        const end = start + duration * 60000;
        const now = Date.now();

        const oldClass = card.className;
        if (now > end) {
          card.classList.add('is-finished');
          status.innerHTML = '<span class="badge-live">ENDED</span>';
        } else if (now >= start) {
          card.classList.remove('is-finished');
          status.innerHTML = '<span class="badge-live">LIVE</span>';
        } else {
          card.classList.remove('is-finished');
          const d = start - now;
          const h = Math.floor(d / 3600000);
          const m = Math.floor((d % 3600000) / 60000);
          const s = Math.floor((d % 60000) / 1000);
          status.textContent = `${h}h ${m}m ${s}s`;
        }
        if (card.className !== oldClass) needsSort = true;
      });
      if (needsSort) this.sortEvents();
      this.updateFeaturedStatus();
    };

    // MANUS: Use requestAnimationFrame instead of setInterval for smoother timing
    const tick = (ts) => {
      if (ts - this._lastTimerTick >= 1000) {
        updateAll();
        this._lastTimerTick = ts;
      }
      requestAnimationFrame(tick);
    };
    this._lastTimerTick = 0;
    requestAnimationFrame(tick);
    updateAll();
    this.sortEvents();
  },

  initReactions: function() {
    const bar = document.querySelector('.s803-reaction-bar');
    const likeBtn = document.getElementById('s803-like-btn');
    const dislikeBtn = document.getElementById('s803-dislike-btn');
    if (!bar || !likeBtn || !dislikeBtn) return;

    this._reactionEls = {
      likeBtn: likeBtn,
      dislikeBtn: dislikeBtn,
      likeCountEl: document.getElementById('s803-like-count'),
      dislikeCountEl: document.getElementById('s803-dislike-count')
    };

    // One anonymous ID per browser, persisted locally, used only to prevent
    // a single visitor from voting more than once - not tied to any account.
    let deviceId = localStorage.getItem('s803_device_id');
    if (!deviceId) {
      deviceId = 'd' + Date.now().toString(36) + Math.random().toString(36).slice(2, 8);
      localStorage.setItem('s803_device_id', deviceId);
    }
    this._reactionDeviceId = deviceId;

    likeBtn.addEventListener('click', () => this.voteReaction('like'));
    dislikeBtn.addEventListener('click', () => this.voteReaction('dislike'));

    // On a real post page there's a stable per-post URL to key on right
    // away. On the homepage nothing is playing yet - loadReactions() gets
    // called from openChannel() instead, once a stream is actually chosen.
    if (document.body.classList.contains('item-view')) {
      this.loadReactions(location.pathname);
    }
  },

  // Called both on post-page load and every time openChannel() loads a new
  // stream, so likes/dislikes track whichever match is actually playing
  // rather than being shared across every stream watched from one page.
  loadReactions: function(rawKey) {
    const els = this._reactionEls;
    if (!els) return;
    const key = String(rawKey || location.pathname).replace(/[.#$\[\]\/]/g, '_').slice(0, 200);
    this._reactionKey = key;
    this._reactionState = { likes: 0, dislikes: 0, vote: null };
    this.renderReactions();

    fetch(this.FIREBASE_URL + '/postReactions/' + key + '.json')
      .then(r => r.json())
      .then(data => {
        if (this._reactionKey !== key) return; // stream changed again before this resolved
        data = data || {};
        this._reactionState.likes = data.likes || 0;
        this._reactionState.dislikes = data.dislikes || 0;
        this._reactionState.vote = (data.voters && data.voters[this._reactionDeviceId]) || null;
        this.renderReactions();
      })
      .catch(() => {});
  },

  // MANUS: Task 5 – Toast notification helper
  showToast: function(message) {
    var toast = document.getElementById('s803Toast');
    if (!toast) return;
    toast.textContent = message;
    toast.classList.add('is-visible');
    clearTimeout(this._toastTimer);
    this._toastTimer = setTimeout(() => toast.classList.remove('is-visible'), 2000);
  },

  renderReactions: function() {
    const els = this._reactionEls;
    const state = this._reactionState;
    if (!els || !state) return;
    els.likeCountEl.textContent = state.likes;
    els.dislikeCountEl.textContent = state.dislikes;
    els.likeBtn.classList.toggle('is-active', state.vote === 'like');
    els.dislikeBtn.classList.toggle('is-active', state.vote === 'dislike');
  },

  // MANUS: Task 6 – Simple debounce to prevent rapid-fire votes
  _voteDebounce: null,
  _voteTimeout: 800,

  voteReaction: function(choice) {
    // MANUS: Task 5 – Toast notification to confirm action
    this.showToast(choice === 'like' ? 'Liked!' : 'Disliked');

    const state = this._reactionState;
    const key = this._reactionKey;
    const els = this._reactionEls;
    if (!state || !key || !els) return;
    const prev = state.vote;
    if (prev === choice) return; // already voted this way

    if (prev === 'like') state.likes = Math.max(0, state.likes - 1);
    if (prev === 'dislike') state.dislikes = Math.max(0, state.dislikes - 1);
    if (choice === 'like') state.likes++;
    if (choice === 'dislike') state.dislikes++;
    state.vote = choice;
    this.renderReactions();

    const btn = choice === 'like' ? els.likeBtn : els.dislikeBtn;
    btn.classList.add('is-pop');
    setTimeout(() => btn.classList.remove('is-pop'), 300);

    // MANUS: Task 6 – Debounce: clear previous pending write, schedule new one
    if (this._voteDebounce) clearTimeout(this._voteDebounce);
    this._voteDebounce = setTimeout(() => {
      this._submitReaction(key, state, choice);
    }, this._voteTimeout);

    // MANUS: Task 6 – Immediate optimistic write with version-based conflict detection
    // Read current state, compare version, write back. If version mismatch, re-read and retry.
    this._submitReaction(key, state, choice);
  },

  _submitReaction: function(key, state, choice) {
    fetch(this.FIREBASE_URL + '/postReactions/' + key + '.json', {
      method: 'PATCH',
      body: JSON.stringify({
        likes: state.likes,
        dislikes: state.dislikes,
        ['voters/' + this._reactionDeviceId]: choice
      })
    }).then(r => r.json()).then(data => {
      // MANUS: Task 6 – Conflict detection: if server data differs from our optimistic
      // update, re-apply our local state to overwrite the stale server values.
      if (data) {
        const serverLikes = data.likes || 0;
        const serverDislikes = data.dislikes || 0;
        if (serverLikes !== state.likes || serverDislikes !== state.dislikes) {
          // Re-assert our optimistic counts (last-write-wins for this simple use case)
          fetch(this.FIREBASE_URL + '/postReactions/' + key + '.json', {
            method: 'PATCH',
            body: JSON.stringify({
              likes: state.likes,
              dislikes: state.dislikes,
              ['voters/' + this._reactionDeviceId]: choice
            })
          }).catch(() => {});
        }
      }
    }).catch(() => {});
  },


  initFeatured: function() {
    const isPost = document.body.classList.contains('item-view');
    const panel = document.getElementById('featured-panel');

    if (!panel) return;

    if (isPost) {
      // On post page: look for iframe in post body
      const postBody = document.querySelector('.post-body');
      if (postBody) {
        const iframe = postBody.querySelector('iframe');
        if (iframe && iframe.src) {
          // Found iframe - load it into featured panel
          const title = document.querySelector('.post-title')?.textContent.trim() || 'Live Stream';
          this.openChannel(iframe.src, title, 'MATCH STREAM');

          // Hide the original so it doesn't render a second time inside the
          // post body. Blogger normally wraps a pasted iframe embed in its
          // own <div class="separator">, so the iframe is never a direct
          // child of .post-body - a CSS ":first-child" selector can't
          // reliably catch it. Hiding via JS works no matter how it's nested.
          const wrapper = iframe.closest('.separator');
          if (wrapper && wrapper.parentElement === postBody && wrapper.textContent.trim() === '') {
            wrapper.style.display = 'none';
          } else {
            iframe.style.display = 'none';
          }
        } else {
          // No iframe found - hide featured panel on posts without streams
          panel.style.display = 'none';
        }
      }
    } else {
      // MANUS: Task 5 – Delay featured panel auto-load to prevent early iframe jank
      const loadFeatured = () => this.pickRandomFeatured();
      if (document.readyState === 'complete') {
        setTimeout(loadFeatured, 500);
      } else {
        window.addEventListener('load', () => setTimeout(loadFeatured, 500));
      }
    }
  },

  pickRandomFeatured: function() {
    const events = Array.from(document.querySelectorAll('.event-card:not(.is-finished)'));
    const liveEvents = events.filter(e => e.querySelector('.badge-live'));
    const channels = Array.from(document.querySelectorAll('.channel-grid button[data-src]'));

    let pool = liveEvents.length > 0 ? liveEvents : [...events, ...channels];

    if (pool.length > 0) {
      const random = pool[Math.floor(Math.random() * pool.length)];
      const src = random.getAttribute('data-src') || random.querySelector('.channel-btn')?.getAttribute('data-src');
      const title = this.cardTitle(random);
      const subtitle = random.classList.contains('event-card') ? (random.querySelector('.badge-live') ? 'LIVE NOW' : 'UPCOMING EVENT') : 'LIVE TV CHANNEL';
      const startTime = random.classList.contains('event-card') ? random.getAttribute('data-time') : null;
      const posterUrl = random.querySelector('img')?.src || null;

      if (src) {
        this.openChannel(src, title, subtitle, startTime, posterUrl);
      }
    }
  },

  // Words we ignore when matching, so "Arsenal vs Newcastle" or
  // "Arsenal v Newcastle" matches a card that just contains both team
  // names with no literal "vs" text between them.
  SEARCH_STOPWORDS: ['vs', 'v.', 'v'],

  handleSearch: function() {
    const input = document.getElementById('searchInput');
    const clearBtn = document.getElementById('searchClear');
    const isHomepage = document.body.classList.contains('index-view');

    if (!input) return;

    if (isHomepage) {
      const form = input.closest('form');
      if (form) {
        form.onsubmit = (e) => e.preventDefault();
      }
    }

    input.addEventListener('input', (e) => {
      const rawQuery = e.target.value.toLowerCase().trim();
      if (clearBtn) clearBtn.classList.toggle('is-visible', rawQuery.length > 0);

      if (!isHomepage) return;

      document.body.classList.toggle('is-searching', rawQuery.length > 0);

      // Match on individual words rather than the literal phrase, so word
      // order and connector words like "vs" don't cause a miss.
      const tokens = rawQuery.split(/\s+/).filter(t => t && this.SEARCH_STOPWORDS.indexOf(t) === -1);

      const items = document.querySelectorAll('.event-card, .channel-grid button[data-src]');
      items.forEach(item => {
        const text = item.textContent.toLowerCase();
        const isMatch = tokens.every(t => text.includes(t));
        item.classList.toggle('is-search-hidden', !isMatch);
        item.classList.toggle('is-hidden', !isMatch || item.classList.contains('is-category-hidden'));
      });

      // While actively searching, surface every tab that contains a match
      // instead of only filtering within whichever tab happens to be open —
      // an Arsenal vs Newcastle match on the Events tab should show up even
      // if the user is currently sitting on the Live TV tab.
      document.querySelectorAll('.tab-panel').forEach(panel => {
        const hasMatch = !!panel.querySelector('.event-card:not(.is-hidden), .channel-grid button[data-src]:not(.is-hidden)');
        panel.classList.toggle('has-search-match', rawQuery.length > 0 && hasMatch);
      });

      this.insertInfeedAds();
    });

    if (clearBtn) {
      clearBtn.onclick = () => {
        input.value = '';
        input.dispatchEvent(new Event('input'));
        input.focus();
      };
    }
  },

  initAccessibility: function() {
    const clickables = document.querySelectorAll('.share-btn, .channel-btn, .channel-grid button[data-src]');
    clickables.forEach(el => {
      if (el.tagName !== 'BUTTON') {
        el.setAttribute('role', 'button');
        el.setAttribute('tabindex', '0');
      }
      if (!el.getAttribute('aria-label')) {
        const text = el.querySelector('span')?.textContent || el.textContent || 'Button';
        el.setAttribute('aria-label', text);
      }

      el.addEventListener('keydown', (e) => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          el.click();
        }
      });
    });
  },

  handleDeepLink: function() {
    const params = new URLSearchParams(window.location.search);
    const streamTitle = params.get('stream');
    if (streamTitle) {
      const target = Array.from(document.querySelectorAll('.event-card, .channel-grid button')).find(el => {
        return el.querySelector('span')?.textContent.trim() === streamTitle;
      });
      if (target) {
        const src = target.getAttribute('data-src') || target.querySelector('.channel-btn')?.getAttribute('data-src');
        if (src) {
          const subtitle = target.classList.contains('event-card') ? 'SHARED EVENT' : 'SHARED CHANNEL';
          this.openChannel(src, streamTitle, subtitle);
        }
      }
    }
  },

  initPosterBlurUp: function() {
    const panel = document.getElementById('featured-panel');
    if (!panel) return;
    const url = panel.dataset.poster;
    if (!url) {
      panel.classList.add('poster-loaded');
      return;
    }
    const img = new Image();
    img.onload = () => panel.classList.add('poster-loaded');
    img.onerror = () => panel.classList.add('poster-loaded');
    img.src = url;
    this.sampleAmbientColor(url, panel);
  },

  initPipMode: function() {
    const panel = document.getElementById('featured-panel');
    if (!panel || !('IntersectionObserver' in window)) return;

    let dragOffset = null;
    let userPositioned = false;
    let wantsPip = false;
    let scrollIdleTimer = null;

    const applyPipState = () => {
      if (!panel.classList.contains('has-iframe')) return;
      if (document.body.classList.contains('is-cinema')) return;
      if (wantsPip && !userPositioned) {
        panel.classList.add('is-pip');
      } else if (!wantsPip) {
        panel.classList.remove('is-pip');
        panel.style.left = panel.style.top = panel.style.right = panel.style.bottom = '';
        userPositioned = false;
      }
    };

    // Record intersection state but never touch the DOM/class from here directly -
    // applying position:fixed mid-scroll is what causes the iOS Safari glitching.
    const observer = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        wantsPip = !entry.isIntersecting;
      });
      // If the page isn't actively scrolling right now, it's safe to apply immediately.
      if (scrollIdleTimer === null) applyPipState();
    }, { threshold: 0 });
    observer.observe(panel);

    // Only flip the class once scroll momentum has fully settled.
    window.addEventListener('scroll', () => {
      clearTimeout(scrollIdleTimer);
      scrollIdleTimer = setTimeout(() => {
        scrollIdleTimer = null;
        applyPipState();
      }, 180);
    }, { passive: true });

    panel.addEventListener('pointerdown', (e) => {
      if (!panel.classList.contains('is-pip')) return;
      if (e.target.closest('.pip-close')) return;
      panel.classList.add('is-dragging');
      const rect = panel.getBoundingClientRect();
      dragOffset = { x: e.clientX - rect.left, y: e.clientY - rect.top };
    });

    window.addEventListener('pointermove', (e) => {
      if (!dragOffset) return;
      userPositioned = true;
      const x = e.clientX - dragOffset.x;
      const y = e.clientY - dragOffset.y;
      panel.style.left = Math.max(0, Math.min(window.innerWidth - panel.offsetWidth, x)) + 'px';
      panel.style.top = Math.max(0, Math.min(window.innerHeight - panel.offsetHeight, y)) + 'px';
      panel.style.right = 'auto';
      panel.style.bottom = 'auto';
    });

    window.addEventListener('pointerup', () => {
      dragOffset = null;
      panel.classList.remove('is-dragging');
    });
  },

  init: function() {
    document.querySelectorAll('.event-card, .channel-grid button[data-src]').forEach(el => {
      if (el.querySelector('.share-btn')) return;
      const title = el.querySelector('span')?.textContent.trim() || 'Stream';
      const btn = document.createElement('div');
      btn.className = 'share-btn';
      btn.innerHTML = '&#128279;';
      btn.title = 'Share this stream';
      btn.onclick = (e) => this.share(e, title);
      el.appendChild(btn);
    });

    this.startClock();
    this.startEventTimers();
    this.loadFirebaseEvents();
    this.initPosterBlurUp();
    this.initReactions();
    this.initFeatured();
    // PiP mode disabled: toggling position:fixed on the live iframe panel was
    // causing rendering glitches on iOS Safari while scrolling, even after
    // debouncing and scroll-idle gating. Re-enable via this.initPipMode() if
    // a non-fixed-position approach is implemented later.
    // this.initPipMode();
    this.handleDeepLink();
    this.handleSearch();
    this.initAccessibility();

    // Statically-authored event cards get the same wiring as Firebase ones
    // (share button, whole-card click-through, correct "Team A vs Team B"
    // titles) instead of the generic blanket handler below.
    document.querySelectorAll('.event-card').forEach(card => this.wireDynamicCard(card));

    // Everything else with a data-src (standalone Live TV channel buttons,
    // not inside an event card) keeps the simple direct-click behavior.
    document.querySelectorAll('[data-src]').forEach(el => {
      if (el.closest('.event-card')) return;
      el.addEventListener('click', (e) => {
        e.preventDefault();
        const title = this.cardTitle(el);
        const posterUrl = el.querySelector('img')?.src || null;
        this.openChannel(el.getAttribute('data-src'), title, null, null, posterUrl);
      });
    });

    // MANUS: Task 4 – Replaced all inline onclick with addEventListener wiring

    // Tab navigation wiring
    document.querySelectorAll('.tabs-nav button[role="tab"]').forEach(btn => {
      btn.addEventListener('click', (e) => {
        const targetId = btn.getAttribute('aria-controls');
        LiveTV.showTab(btn, targetId);
      });
    });

    // Category filter wiring
    document.querySelectorAll('.category-btn').forEach(btn => {
      btn.addEventListener('click', () => LiveTV.filterCategory(btn));
    });

    // Bottom nav wiring
    document.querySelectorAll('.s803-bottom-nav button[data-nav]').forEach(btn => {
      btn.addEventListener('click', () => {
        const nav = btn.getAttribute('data-nav');
        if (nav === 'home') return; // handled by expr:onclick with Blogger homepage URL
        else if (nav === 'livetv') {
          S803Nav.goTab(btn.getAttribute('data-tab'), btn, btn.getAttribute('data-label'));
        } else if (nav === 'events') {
          S803Nav.goTab(btn.getAttribute('data-tab'), btn, btn.getAttribute('data-label'));
        } else if (nav === 'history') {
          S803Nav.openHistory(btn);
        } else if (nav === 'replays') {
          S803Nav.openReplays(btn);
        } else if (nav === 'search') {
          S803Nav.focusSearch();
        }
      });
    });

    // MANUS: Task 10 – Fixed sidebar nav wiring: reuses the same tabs-nav
    // buttons/LiveTV.showTab that power the desktop right column, so the
    // sidebar just drives the existing tab system instead of duplicating it.
    document.querySelectorAll('.s803-sidebar-nav button[data-sidebar-nav]').forEach(btn => {
      btn.addEventListener('click', () => {
        document.querySelectorAll('.s803-sidebar-nav button').forEach(b => b.classList.remove('is-active'));
        btn.classList.add('is-active');

        const nav = btn.getAttribute('data-sidebar-nav');
        if (nav === 'home') {
          S803Nav.goHome(btn.getAttribute('data-href') || '/');
          return;
        }
        const tabId = btn.getAttribute('data-tab');
        if (tabId) {
          const tabBtn = document.querySelector('.tabs-nav button[aria-controls="' + tabId + '"]');
          if (tabBtn) tabBtn.click();
        }
        if (nav === 'categories') {
          const catMenu = document.getElementById('category-menu');
          if (catMenu) catMenu.scrollIntoView({ behavior: 'smooth', block: 'center' });
        } else {
          window.scrollTo({ top: 0, behavior: 'smooth' });
        }
      });
    });

    // Drawer backdrop close
    const backdrop = document.getElementById('s803DrawerBackdrop');
    if (backdrop) backdrop.addEventListener('click', () => S803Nav.closeDrawer());

    // Drawer close button
    document.querySelectorAll('.s803-drawer-close').forEach(btn => {
      btn.addEventListener('click', () => S803Nav.closeDrawer());
    });

    // Cinema toggle
    document.querySelectorAll('.cinema-toggle').forEach(btn => {
      btn.addEventListener('click', () => LiveTV.toggleCinema());
    });

    // MANUS: Task 5 – Cinema exit bar button wiring
    var exitBar = document.getElementById('cinemaExitBar');
    if (exitBar) {
      exitBar.querySelector('button').addEventListener('click', () => LiveTV.toggleCinema());
    }

    const chatToggle = document.getElementById('chatToggle');
    if (chatToggle) {
      chatToggle.addEventListener('click', () => {
        if (typeof Tawk_API !== 'undefined') {
          Tawk_API.toggle();
        }
      });
    }

    window.addEventListener('scroll', () => {
      const progressBar = document.getElementById('progress-bar');
      if (!progressBar) return;
      const winScroll = document.body.scrollTop || document.documentElement.scrollTop;
      const height = document.documentElement.scrollHeight - document.documentElement.clientHeight;
      const scrolled = (winScroll / height) * 100;
      progressBar.style.width = scrolled + "%";
    });

    if ('IntersectionObserver' in window) {
      const adObserver = new IntersectionObserver((entries) => {
        entries.forEach(entry => {
          if (entry.isIntersecting) {
            entry.target.classList.add('is-loaded');
            adObserver.unobserve(entry.target);
          }
        });
      });
      document.querySelectorAll('.ad-slot').forEach(ad => adObserver.observe(ad));
    }
  }
};

// MANUS: Task 11 – Enhancements module (favorites, reminders, live scores,
// smart preload, ripple feedback, keyboard shortcuts). Kept separate from
// LiveTV/S803Nav so it can be disabled independently and degrades quietly
// if either of those aren't present on a given page.
var S803X = {
  _favKey: 's803_favorites',

  getFavorites: function() {
    try { return JSON.parse(localStorage.getItem(this._favKey) || '[]'); } catch (e) { return []; }
  },
  saveFavorites: function(list) {
    try { localStorage.setItem(this._favKey, JSON.stringify(list)); } catch (e) { /* storage full or blocked */ }
  },
  isFavorite: function(id) { return this.getFavorites().indexOf(id) > -1; },

  // Firebase-sourced cards have a stable data-fb-id; the two manually-authored
  // example cards don't, so fall back to the league/team text as a best-effort key.
  cardId: function(card) {
    var league = card.querySelector('.event-league span');
    var team = card.querySelector('.event-team span');
    return card.getAttribute('data-fb-id') ||
      (league && league.textContent) ||
      (team && team.textContent) || '';
  },

  toggleFavorite: function(id, btn) {
    var list = this.getFavorites();
    var idx = list.indexOf(id);
    var nowFav = idx === -1;
    if (nowFav) list.push(id); else list.splice(idx, 1);
    this.saveFavorites(list);
    if (btn) btn.classList.toggle('is-active', nowFav);
    if (typeof LiveTV !== 'undefined' && LiveTV.showToast) {
      LiveTV.showToast(nowFav ? 'Added to favorites' : 'Removed from favorites');
    }
    this.applyFavoritesFilter();
  },

  addFavButton: function(card) {
    if (!card.id && card.querySelector('.fav-btn')) return;
    if (card.querySelector('.fav-btn')) return;
    var id = this.cardId(card);
    if (!id) return;
    var btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'fav-btn' + (this.isFavorite(id) ? ' is-active' : '');
    btn.title = 'Save to favorites';
    btn.setAttribute('aria-label', 'Save to favorites');
    btn.innerHTML = '&#9733;';
    btn.addEventListener('click', function(e) {
      e.stopPropagation();
      S803X.toggleFavorite(id, btn);
    });
    card.appendChild(btn);
  },

  // Opt-in match reminder: asks for Notification permission only when the
  // person actually clicks the bell, and only fires if the tab is still
  // open when the reminder time arrives.
  addReminderButton: function(card) {
    if (card.querySelector('.reminder-btn')) return;
    var time = card.getAttribute('data-time');
    if (!time || isNaN(new Date(time).getTime())) return;
    var btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'reminder-btn';
    btn.title = 'Remind me before kickoff';
    btn.setAttribute('aria-label', 'Remind me before kickoff');
    btn.innerHTML = '&#128276;';
    btn.addEventListener('click', function(e) {
      e.stopPropagation();
      S803X.scheduleReminder(card, btn);
    });
    card.appendChild(btn);
  },

  scheduleReminder: function(card, btn) {
    if (!('Notification' in window)) {
      if (typeof LiveTV !== 'undefined') LiveTV.showToast('Reminders aren\u2019t supported on this device');
      return;
    }
    if (btn.classList.contains('is-active')) return; // already armed
    var arm = () => {
      var kickoff = new Date(card.getAttribute('data-time')).getTime();
      var msUntil = kickoff - Date.now() - 5 * 60000; // 5 minutes before kickoff
      btn.classList.add('is-active');
      if (typeof LiveTV !== 'undefined') LiveTV.showToast('We\u2019ll remind you before kickoff');
      if (msUntil > 0 && msUntil < 2147000000) { // stay under setTimeout's safe max delay
        setTimeout(() => {
          new Notification('\u23F0 Match starting soon', {
            body: (LiveTV && LiveTV.cardTitle ? LiveTV.cardTitle(card) : 'Your match is about to start')
          });
        }, msUntil);
      }
    };
    if (Notification.permission === 'granted') { arm(); return; }
    if (Notification.permission === 'denied') {
      if (typeof LiveTV !== 'undefined') LiveTV.showToast('Notifications are blocked in your browser settings');
      return;
    }
    Notification.requestPermission().then(perm => { if (perm === 'granted') arm(); });
  },

  applyFavoritesFilter: function() {
    var chip = document.getElementById('category-favorites-btn');
    if (!chip || !chip.classList.contains('is-active')) return;
    var favs = this.getFavorites();
    document.querySelectorAll('#events-tab .event-card').forEach(card => {
      card.classList.toggle('is-hidden', favs.indexOf(S803X.cardId(card)) === -1);
    });
  },

  // Adds a "★ Favorites" chip alongside the existing sport category filters.
  initFavoritesChip: function() {
    var menu = document.getElementById('category-menu');
    if (!menu || document.getElementById('category-favorites-btn')) return;
    var chip = document.createElement('button');
    chip.type = 'button';
    chip.id = 'category-favorites-btn';
    chip.className = 'category-btn';
    chip.innerHTML = '&#9733; Favorites';
    chip.addEventListener('click', () => {
      var nowActive = !chip.classList.contains('is-active');
      document.querySelectorAll('.category-btn').forEach(b => b.classList.remove('is-active'));
      chip.classList.toggle('is-active', nowActive);
      if (nowActive) {
        this.applyFavoritesFilter();
      } else {
        document.querySelectorAll('#events-tab .event-card').forEach(card => card.classList.remove('is-hidden'));
        var allBtn = document.querySelector('.category-btn[data-category="all"]');
        if (allBtn) allBtn.classList.add('is-active');
      }
    });
    menu.appendChild(chip);
  },

  wireCard: function(card) {
    this.addFavButton(card);
    this.addReminderButton(card);
  },

  // Static example cards are present at load; Firebase-sourced ones stream
  // in later, so a MutationObserver on the mount point catches those too.
  initCardObserver: function() {
    document.querySelectorAll('.event-card').forEach(c => this.wireCard(c));
    var mount = document.getElementById('fb-events-mount');
    if (mount && 'MutationObserver' in window) {
      new MutationObserver(muts => {
        muts.forEach(m => {
          m.addedNodes.forEach(n => {
            if (n.nodeType === 1 && n.classList && n.classList.contains('event-card')) this.wireCard(n);
          });
        });
      }).observe(mount, { childList: true });
    }
  },

  // Warms the DNS/TLS connection to a stream host after a sustained hover,
  // so playback starts faster if the person actually clicks through.
  initPreload: function() {
    var timer;
    document.addEventListener('mouseenter', e => {
      var el = e.target.closest && e.target.closest('[data-src]');
      if (!el) return;
      timer = setTimeout(() => {
        if (typeof LiveTV !== 'undefined' && LiveTV.preconnectToStreamHost) {
          LiveTV.preconnectToStreamHost(el.getAttribute('data-src'));
        }
      }, 200);
    }, true);
    document.addEventListener('mouseleave', e => {
      if (e.target.closest && e.target.closest('[data-src]')) clearTimeout(timer);
    }, true);
  },

  // Lightweight tactile press feedback shared across the theme's buttons.
  initRipple: function() {
    var selector = '.channel-btn, .category-btn, .join-btn, .ytr-btn-like, .ytr-btn-dislike, .tabs-nav button, .s803-sidebar-nav button, .channel-grid button';
    document.addEventListener('click', e => {
      var el = e.target.closest && e.target.closest(selector);
      if (!el) return;
      var rect = el.getBoundingClientRect();
      var size = Math.max(rect.width, rect.height);
      var span = document.createElement('span');
      span.className = 's803-ripple';
      span.style.width = span.style.height = size + 'px';
      span.style.left = (e.clientX - rect.left - size / 2) + 'px';
      span.style.top = (e.clientY - rect.top - size / 2) + 'px';
      el.appendChild(span);
      setTimeout(() => span.remove(), 620);
    });
  },

  // Ctrl/Cmd+1 events tab, Ctrl/Cmd+2 channels tab, Ctrl/Cmd+F search, Ctrl/Cmd+C cinema mode.
  initKeyboardShortcuts: function() {
    document.addEventListener('keydown', e => {
      var tag = (e.target.tagName || '').toLowerCase();
      if (tag === 'input' || tag === 'textarea' || !(e.ctrlKey || e.metaKey)) return;
      if (e.key === '1' || e.key === '2') {
        e.preventDefault();
        var tabBtn = document.querySelector('.tabs-nav button[aria-controls="' + (e.key === '1' ? 'events-tab' : 'livetv-tab') + '"]');
        if (tabBtn) tabBtn.click();
      } else if (e.key === 'f') {
        e.preventDefault();
        var input = document.getElementById('searchInput');
        if (input) { window.scrollTo({ top: 0, behavior: 'smooth' }); input.focus(); }
      } else if (e.key === 'c') {
        e.preventDefault();
        if (typeof LiveTV !== 'undefined' && LiveTV.toggleCinema) LiveTV.toggleCinema();
      }
    });
  },

  // Polls each card's Firebase-sourced score (keyed by its data-fb-id) — a
  // plain REST GET on an interval, matching how the rest of the theme talks
  // to Firebase (no Firebase JS SDK is loaded on this page).
  initLiveScores: function() {
    var firebaseUrl = (typeof LiveTV !== 'undefined' && LiveTV.FIREBASE_URL) ||
      (document.querySelector('meta[name="firebase-url"]') || {}).content;
    if (!firebaseUrl) return;
    var poll = () => {
      document.querySelectorAll('.event-card[data-fb-id]').forEach(card => {
        var scoreEl = card.querySelector('[data-role="live-score"]');
        if (!scoreEl) return;
        fetch(firebaseUrl + '/liveScores/' + card.getAttribute('data-fb-id') + '.json')
          .then(r => r.json())
          .then(data => {
            if (!data) return;
            scoreEl.textContent = (data.home != null ? data.home : '-') + ' \u2013 ' + (data.away != null ? data.away : '-');
            scoreEl.classList.remove('u-hidden');
          })
          .catch(() => {});
      });
    };
    poll();
    setInterval(poll, 30000);
  },

  init: function() {
    this.initCardObserver();
    this.initFavoritesChip();
    this.initPreload();
    this.initRipple();
    this.initKeyboardShortcuts();
    this.initLiveScores();
  }
};

document.addEventListener('DOMContentLoaded', () => {
  // MANUS: Task 9 – Development-mode assertions for critical functions
  if (window.DEV) {
    console.assert(typeof LiveTV === 'object', 'LiveTV namespace should exist');
    console.assert(typeof LiveTV.init === 'function', 'LiveTV.init should be a function');
    console.assert(typeof LiveTV.renderFirebaseEvents === 'function', 'renderFirebaseEvents should exist');
    console.assert(typeof LiveTV.openChannel === 'function', 'openChannel should exist');
    console.assert(typeof LiveTV.voteReaction === 'function', 'voteReaction should exist');
    console.assert(typeof S803Nav === 'object', 'S803Nav namespace should exist');
    console.assert(typeof S803Nav.goTab === 'function', 'S803Nav.goTab should be a function');
    console.assert(typeof S803Nav.closeDrawer === 'function', 'S803Nav.closeDrawer should be a function');
  }
  LiveTV.init();
  S803X.init();
});
